import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Avatar from 'flarum/common/components/Avatar';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import extractText from 'flarum/common/utils/extractText';
import { call, rarityName, t } from '../util';
export function openTrade(attrs = {}) {
  app.modal.show(TradeModal, attrs);
}

/**
 * Offer spares to another member, optionally asking for some of theirs.
 * Only spares are listed (one copy always stays in the album); the server
 * checks all of it again, and again when the offer is accepted.
 */
export default class TradeModal extends Modal {
  /** Sticker id → how many. */

  oninit(vnode) {
    super.oninit(vnode);
    this.to = this.attrs.to || null;
    this.give = new Map(this.attrs.give || []);
    this.take = new Map(this.attrs.take || []);
    this.message = '';
    this.mine = null;
    this.theirs = null;
    this.query = '';
    this.results = [];
    const me = app.session.user;
    this.album(me.slug()).then(album => this.mine = album);
    if (this.to) this.loadTheirs();
  }
  className() {
    return 'StickerTradeModal';
  }
  title() {
    return t('trade.title');
  }
  album(slug) {
    return call('GET', '/album', {
      user: slug
    }).finally(() => m.redraw());
  }
  loadTheirs() {
    this.theirs = null;
    this.album(this.to.slug).then(album => this.theirs = album);
  }
  content() {
    const ready = this.to && this.give.size;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "StickerTrade-to"
    }, m("label", null, t('trade.to')), this.to ? this.person(this.to) : this.picker()), this.sides(), m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      maxlength: "200",
      placeholder: extractText(t('trade.message_placeholder')),
      value: this.message,
      oninput: e => this.message = e.target.value
    })), m(Button, {
      className: "Button Button--primary Button--block",
      icon: "fas fa-paper-plane",
      disabled: !ready,
      loading: this.loading,
      onclick: () => this.send()
    }, this.take.size ? t('trade.send') : t('trade.send_gift')));
  }

  /** The member the offer is for, with a way to pick someone else (unless the window was opened for them). */
  person(to) {
    return m("div", {
      className: "StickerTrade-person"
    }, m(Avatar, {
      user: app.store.getById('users', String(to.id)) || null
    }), m("strong", null, to.displayName), this.attrs.to ? null : m(Button, {
      className: "Button Button--link",
      onclick: () => (this.to = null, this.theirs = null, this.take.clear())
    }, t('trade.change')));
  }

  /** What the member gives, and what they get (once they've picked whom from). */
  sides() {
    return m("div", {
      className: "StickerTrade-sides"
    }, this.side(t('trade.you_give'), this.mine, this.give, this.take, true), m("div", {
      className: "StickerTrade-swap",
      "aria-hidden": "true"
    }, m(Icon, {
      name: "fas fa-right-left"
    })), this.to ? this.side(t('trade.you_get', {
      name: this.to.displayName
    }), this.theirs, this.take, this.give, false) : m("div", {
      className: "StickerTrade-side is-waiting"
    }, m("h4", null, t('trade.you_get_anyone')), m("p", {
      className: "StickerTrade-hint"
    }, t('trade.pick_member_first'))));
  }
  picker() {
    return m("div", {
      className: "StickerTrade-picker"
    }, m("input", {
      className: "FormControl",
      placeholder: extractText(t('trade.search_placeholder')),
      value: this.query,
      oninput: e => this.search(e.target.value),
      autocomplete: "off"
    }), this.results.length ? m("ul", {
      className: "StickerTrade-results"
    }, this.results.map(u => m("li", null, m("button", {
      type: "button",
      onclick: () => {
        this.to = {
          id: Number(u.id()),
          displayName: u.displayName(),
          slug: u.slug()
        };
        this.results = [];
        this.query = '';
        this.loadTheirs();
      }
    }, m(Avatar, {
      user: u
    }), " ", u.displayName())))) : null);
  }
  search(value) {
    this.query = value;
    clearTimeout(this.timer);
    if (value.trim().length < 2) {
      this.results = [];
      return;
    }
    this.timer = setTimeout(() => {
      app.store.find('users', {
        filter: {
          q: value.trim()
        },
        page: {
          limit: 6
        }
      }).then(users => {
        this.results = users.filter(u => u !== app.session.user);
        m.redraw();
      }).catch(() => {
        /* app.request already showed the error */
      });
    }, 250);
  }

  /** One side: that member's spares, tap to add, − / + for how many. */
  side(title, album, chosen, other, mine) {
    if (!album) {
      return m("div", {
        className: "StickerTrade-side"
      }, m("h4", null, title), m(LoadingIndicator, {
        size: "small"
      }));
    }
    const spares = album.sets.flatMap(set => set.stickers).filter(s => s.count > 1 && !other.has(s.id));
    return m("div", {
      className: "StickerTrade-side"
    }, m("h4", null, title), spares.length ? m("div", {
      className: "StickerTrade-grid"
    }, spares.map(s => this.spare(s, chosen))) : m("p", {
      className: "StickerTrade-hint"
    }, mine ? t('trade.no_spares_mine') : t('trade.no_spares_theirs')));
  }

  /** One spare: tap to add or take out, − / + for how many (one copy always stays). */
  spare(s, chosen) {
    const n = chosen.get(s.id) || 0;
    const max = s.count - 1;
    return m("div", {
      className: `StickerTrade-item StickerTile--r${s.rarity} ${n ? 'is-chosen' : ''}`
    }, m("button", {
      type: "button",
      className: "StickerTrade-pick",
      title: `${s.name} · ${rarityName(s.rarity)}`,
      "aria-pressed": n ? 'true' : 'false',
      onclick: () => n ? chosen.delete(s.id) : chosen.set(s.id, 1)
    }, m("img", {
      src: s.small,
      alt: s.name,
      draggable: "false"
    }), m("span", {
      className: "StickerTrade-spare"
    }, n ? `${n}/${max}` : `×${max}`)), n ? m("span", {
      className: "StickerTrade-stepper"
    }, m("button", {
      type: "button",
      "aria-label": "\u2212",
      onclick: () => n > 1 ? chosen.set(s.id, n - 1) : chosen.delete(s.id)
    }, "\u2212"), m("button", {
      type: "button",
      "aria-label": "+",
      disabled: n >= max,
      onclick: () => chosen.set(s.id, Math.min(max, n + 1))
    }, "+")) : null);
  }
  send() {
    const to = this.to;
    this.loading = true;
    call('POST', '/trades', {
      to: to.id,
      give: [...this.give.entries()],
      take: [...this.take.entries()],
      message: this.message
    }).then(() => {
      this.hide();
      app.alerts.show({
        type: 'success'
      }, t('trade.sent', {
        name: to.displayName
      }));
      window.dispatchEvent(new CustomEvent('sticker-book:changed'));
    }).catch(() => {
      /* call() already showed the error */
    }).finally(() => {
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-sticker-book', 'forum/components/TradeModal', TradeModal);